            return Not(_parse_not_expr())
        return _parse_comparison()

    def _parse_and_expr() -> Expr:
        left = _parse_not_expr()
        while _peek(TokenType.KEYWORD) and tokens[0].value == "AND":
            _consume(TokenType.KEYWORD)  # AND
            right = _parse_not_expr()
            left = And(left, right)
        return left

    def _parse_or_expr() -> Expr:
        left = _parse_and_expr()
        while _peek(TokenType.KEYWORD) and tokens[0].value == "OR":
            _consume(TokenType.KEYWORD)  # OR
            right = _parse_and_expr()
            left = Or(left, right)
        return left

    expr = _parse_or_expr()
    if not _peek(TokenType.EOF):
        raise SQLSyntaxError("Trailing tokens found in expression")
    _consume(TokenType.EOF)
    return expr
